import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"罗伊·丁斯代尔","description":"","frontmatter":{"title":"罗伊·丁斯代尔","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/罗伊·丁斯代尔.md","filePath":"04_people/罗伊·丁斯代尔.md"}'),o={name:"04_people/罗伊·丁斯代尔.md"};function s(n,a,i,_,d,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="罗伊·丁斯代尔-roy-dinsdale" tabindex="-1">罗伊·丁斯代尔（Roy Dinsdale） <a class="header-anchor" href="#罗伊·丁斯代尔-roy-dinsdale" aria-label="Permalink to &quot;罗伊·丁斯代尔（Roy Dinsdale）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：堪萨斯银行家担保公司（Kansas Bankers Surety）相关人士</li><li><strong>与巴菲特关系</strong>：其公司被伯克希尔收购，成为伯克希尔保险帝国的一部分</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>罗伊·丁斯代尔与堪萨斯银行家担保公司（Kansas Bankers Surety）有着密切的关联。堪萨斯银行家担保公司是一家位于堪萨斯州的小型保险公司，专注于为银行提供担保和保险服务。该公司历史悠久，在银行业担保领域积累了丰富的经验和良好的信誉。伯克希尔·哈撒韦在保险业务扩张的过程中，收购了多家中小型专业保险公司，堪萨斯银行家担保公司正是其中之一。丁斯代尔作为这家公司的核心人物，在公司被伯克希尔收购的过程中发挥了关键作用，并在此后继续参与公司运营。伯克希尔的保险帝国是其投资帝国的基石，收购这类专业保险公司是巴菲特长期战略的重要组成部分。丁斯代尔代表了伯克希尔众多被收购的中小型保险公司的创始人群体——专业、专注、与伯克希尔文化高度契合。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>伯克希尔收购前</strong>：丁斯代尔长期担任堪萨斯银行家担保公司的核心领导</li><li><strong>被收购后</strong>：继续在伯克希尔体系内为堪萨斯银行家担保公司提供专业管理</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=罗伊·丁斯代尔在1996年股东信中的原话">1996年：完整翻译|/01_letters/1996年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",s]]);export{c as __pageData,u as default};
